ST.xhtml:p:
IF g_nSusutainCount >= 1 THEN
  bSustainAxis1Enable := TRUE;
  IF g_biAxIsYisHome AND NOT g_bSupportAxis1ShieldFlag THEN
    (*支撑轴1下降标志位 = Y轴当前坐标 -（支撑轴1在Y上坐标 - 支撑轴1提前下降距离）*)
    bSustainAxis1SafeDownFlag := g_fCurrentCoordYBuffer >= (g_fSupAxisCoordY1 - g_fSupAxisDownDis1);
  ELSE
    bSustainAxis1SafeDownFlag := FALSE;
  END_IF;
  bSustainAxis1SafeDown := bSustainAxis1SafeDownFlag AND NOT g_bSustain1InFollow;(*支撑轴1已经达到下降条件，并且浮动已关闭*)
  g_bSustainAxis1UpFeedSafe := NOT bSustainAxis1SafeDownFlag;(*支撑轴1可浮动*)
  bSustainAxis1FloatEnable := g_bSustainAxis1UpFeedSafe AND bSustainAxis1Enable AND (NOT g_bSustain1Switch);(*能不能开浮动标志位*)
END_IF;
