IF RTrigger1.Q THEN
	g_dSupportAxis1ActPos := Axis_Sustain1.NCTOPLC.ACTPOS;
    IF g_bSustainAxis1VelAddEnable THEN
      g_bSustainAxis1VelAddEnable := FALSE;
      g_Sustain1Stop.EXECUTE := TRUE;
      nSustain1DownState := 10;
    ELSE
      IF Axis_Sustain1.NCTOPLC.ACTPOS >= 0.00000001 THEN
        g_bSustain1AbsPosition := 0.0;
		g_bSustain1Abs := TRUE;
      END_IF;
    END_IF;
	g_bSupportAxisMoveLossenAntiCyl1 := TRUE;
END_IF;



CASE nSustain1DownState OF
  0:
	nSustain1DownState := 0;
  10:
	IF g_Sustain1Stop.DONE THEN
		g_Sustain1Stop.EXECUTE := FALSE;
		IF Axis_Sustain1.NCTOPLC.ACTPOS >= 0.00000001 THEN
			g_bSustain1AbsPosition := 0.0;
