R_TrrigerM319(CLK := g_bSupportPendingControlM);
IF R_TrrigerM319.Q THEN
  g_bSupportPendingControlM := FALSE;
  g_bSupportPendingFlag := FALSE;
  IF NOT g_bSupportFollowEnable OR g_nPipeType =1 THEN
	M.ENABLE[319] := 0;
  ELSE
	  IF M.PARAMETER_P[319] = 0.0 THEN
		  IF ABS(M.PARAMETER_Q[319]) >= 180.0 THEN
			IF g_nSusutainCount >= 1 AND g_bSustainAxis1UpFeedSafe AND g_bSustainAxis1VelAddEnable THEN
				g_bSupportPendingFlag := TRUE;
                g_bSustain1AbsPosition := g_fSustain1ToChuckDist - SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0);
                g_bSustain1Abs := TRUE;
			END_IF;

			IF g_nSusutainCount >= 2 AND g_bSustainAxis2UpFeedSafe AND g_bSustainAxis2VelAddEnable THEN
			  g_bSupportPendingFlag := TRUE;
			  g_bSustain2AbsPosition := g_fSustain2ToChuckDist - SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0);
			  g_bSustain2Abs := TRUE;
			END_IF;
			IF g_nSusutainCount >= 3 AND g_bSustainAxis3UpFeedSafe AND g_bSustainAxis3VelAddEnable THEN
			  g_bSupportPendingFlag := TRUE;
			  g_bSustain3AbsPosition := g_fSustain3ToChuckDist - SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0);
			  g_bSustain3Abs := TRUE;
			END_IF;
			IF g_nSusutainCount >= 4 AND g_bSustainAxis7UpFeedSafe AND g_bSustainAxis4VelAddEnable THEN
			  g_bSupportPendingFlag := TRUE;
			  g_bSustain7AbsPosition := g_fSustain7ToChuckDist - SQRT(g_dSquareLenght*g_dSquareLenght/4.0 + g_dSquareWidth*g_dSquareWidth/4.0);
			  g_bSustain7Abs := TRUE;
			END_IF;
			IF g_nSusutainCount >= 5 AND g_bSustainAxis8UpFeedSafe AND g_bSustainAxis5VelAddEnable THEN
			  g_bSupportPendingFlag := TRUE;
