      (*浮动*)
      nFollowStep := 10;
    END_IF;
    g_boSustainFollowDone := FALSE;
  ELSE
    g_boSustainFollowDone := TRUE;
    M.ENABLE[193] := 0;
    g_bExecuteFinishedM193 := FALSE;
    g_bFinishedM193_1 := FALSE;
  END_IF;
  g_bSustainFollowExecuteM := FALSE;
END_IF;

