    IF ((g_bSustain1AbsDone AND bSustainAxis1FloatEnable (*AND ABS(Axis_Sustain1.NcToPlc.ActPos - g_bSustain1AbsPosition) < 0.0001*)) OR NOT bSustainAxis1FloatEnable)
        AND ((g_bSustain2AbsDone AND bSustainAxis2FloatEnable (*AND ABS(Axis_Sustain2.NcToPlc.ActPos - g_bSustain2AbsPosition) < 0.0001*)) OR NOT bSustainAxis2FloatEnable) THEN
        bSustainAxesFloatUp := FALSE;
       (* g_bSustain1Follow := bSustainAxis1FloatEnable;
        g_bSustain2Follow := bSustainAxis2FloatEnable;*)
        nFollowStep := 30;
    END_IF;
  ELSIF g_nSusutainCount = 1 THEN
    IF ((g_bSustain1AbsDone AND bSustainAxis1FloatEnable (*AND ABS(Axis_Sustain1.NcToPlc.ActPos - g_bSustain1AbsPosition) < 0.0001*)) OR NOT bSustainAxis1FloatEnable) THEN
        bSustainAxesFloatUp := FALSE;
        (*g_bSustain1Follow := bSustainAxis1FloatEnable;*)
        nFollowStep := 30;
    END_IF;
  END_IF;
  30:
    nFollowStep := 0;
    g_boSustainFollowDone := TRUE;
    M.ENABLE[193] := 0;
    g_bExecuteFinishedM193 := FALSE;
    g_bFinishedM193_1 := FALSE;
  100:
    IF g_nSusutainCount >= 1 THEN
      g_bSustainAxis1VelAddEnable := FALSE;
    END_IF;
    IF g_nSusutainCount >= 2 THEN
      g_bSustainAxis2VelAddEnable := FALSE;
    END_IF;
    IF g_nSusutainCount >= 3 THEN
      g_bSustainAxis3VelAddEnable := FALSE;
    END_IF;
    IF g_nSusutainCount >= 4 THEN
      g_bSustainAxis4VelAddEnable := FALSE;
    END_IF;
    IF g_nSusutainCount >= 5 THEN
      g_bSustainAxis5VelAddEnable := FALSE;
    END_IF;
    IF g_nSusutainCount >= 6 THEN
      g_bSustainAxis6VelAddEnable := FALSE;
    END_IF;
    IF g_nSusutainCount >= 7 THEN
      g_bSustainAxis7VelAddEnable := FALSE;
    END_IF;
    IF g_nSusutainCount >= 8 THEN
      g_bSustainAxis8VelAddEnable := FALSE;
    END_IF;
    IF g_nSusutainCount >= 9 THEN
      g_bSustainAxis9VelAddEnable := FALSE;
    END_IF;
    IF g_nSusutainCount >= 10 THEN
      g_bSustainAxis10VelAddEnable := FALSE;
    END_IF;
    IF g_nSusutainCount >= 11 THEN
      g_bSustainAxis11VelAddEnable := FALSE;
    END_IF;
    IF g_nSusutainCount >= 12 THEN
      g_bSustainAxis12VelAddEnable := FALSE;
    END_IF;
    nFollowStep := 110;
  110:(*关随动后支撑轴下降*)
  IF g_nSusutainCount >= 1 THEN
    g_bSustain1Abs := TRUE;
    IF Axis_Sustain1.NCTOPLC.SETPOS <= 0.0 THEN
      g_bSustain1AbsPosition := Axis_Sustain1.NCTOPLC.SETPOS;
    ELSE
      g_bSustain1AbsPosition := 0.0;
    END_IF;
  END_IF;
  IF g_nSusutainCount >= 2 THEN
    g_bSustain2Abs := TRUE;
    IF Axis_Sustain2.NCTOPLC.SETPOS <= 0.0 THEN
      g_bSustain2AbsPosition := Axis_Sustain2.NCTOPLC.SETPOS;
    ELSE
      g_bSustain2AbsPosition := 0.0;
    END_IF;
  END_IF;
  IF g_nSusutainCount >= 3 THEN
    g_bSustain3Abs := TRUE;
    IF Axis_Sustain3.NCTOPLC.SETPOS <= 0.0 THEN
      g_bSustain3AbsPosition := Axis_Sustain3.NCTOPLC.SETPOS;
    ELSE
      g_bSustain3AbsPosition := 0.0;
    END_IF;
  END_IF;
  IF g_nSusutainCount >= 4 THEN
    g_bSustain7Abs := TRUE;
    IF Axis_Sustain7.NCTOPLC.SETPOS <= 0.0 THEN
      g_bSustain7AbsPosition := Axis_Sustain7.NCTOPLC.SETPOS;
    ELSE
      g_bSustain7AbsPosition := 0.0;
    END_IF;
  END_IF;
  IF g_nSusutainCount >= 5 THEN
    g_bSustain8Abs := TRUE;
    IF Axis_Sustain8.NCTOPLC.SETPOS <= 0.0 THEN
      g_bSustain8AbsPosition := Axis_Sustain8.NCTOPLC.SETPOS;
    ELSE
      g_bSustain8AbsPosition := 0.0;
    END_IF;
  END_IF;
  IF g_nSusutainCount >= 6 THEN
    g_bSustain9Abs := TRUE;
    IF Axis_Sustain9.NCTOPLC.SETPOS <= 0.0 THEN
      g_bSustain9AbsPosition := Axis_Sustain9.NCTOPLC.SETPOS;
    ELSE
      g_bSustain9AbsPosition := 0.0;
    END_IF;
  END_IF;
  IF g_nSusutainCount >= 7 THEN
    IF Axis_S7.NCTOPLC.SETPOS <= 0.0 THEN
      g_NCMoveData.NCAXISDATA[4].AxisAbsPosition := Axis_S7.NCTOPLC.SETPOS;
    ELSE
      g_NCMoveData.NCAXISDATA[4].AxisAbsPosition := 0.0;
    END_IF;
    g_NCMoveData.NCAXISCMD[4].NCAxisAbs := TRUE;
  END_IF;
  IF g_nSusutainCount >= 5 THEN
    IF Axis_S8.NCTOPLC.SETPOS <= 0.0 THEN
      g_NCMoveData.NCAXISDATA[5].AxisAbsPosition := Axis_S8.NCTOPLC.SETPOS;
    ELSE
      g_NCMoveData.NCAXISDATA[5].AxisAbsPosition := 0.0;
    END_IF;
    g_NCMoveData.NCAXISCMD[5].NCAxisAbs := TRUE;
  END_IF;
  IF g_nSusutainCount >= 9 THEN
    IF Axis_S9.NCTOPLC.SETPOS <= 0.0 THEN
      g_NCMoveData.NCAXISDATA[6].AxisAbsPosition := Axis_S9.NCTOPLC.SETPOS;
    ELSE
      g_NCMoveData.NCAXISDATA[6].AxisAbsPosition := 0.0;
    END_IF;
    g_NCMoveData.NCAXISCMD[6].NCAxisAbs := TRUE;
  END_IF;
  IF g_nSusutainCount >= 10 THEN
    IF Axis_S10.NCTOPLC.SETPOS <= 0.0 THEN
      g_NCMoveData.NCAXISDATA[7].AxisAbsPosition := Axis_S10.NCTOPLC.SETPOS;
    ELSE
      g_NCMoveData.NCAXISDATA[7].AxisAbsPosition := 0.0;
    END_IF;
    g_NCMoveData.NCAXISCMD[7].NCAxisAbs := TRUE;
  END_IF;
  IF g_nSusutainCount >= 11 THEN
    IF Axis_S11.NCTOPLC.SETPOS <= 0.0 THEN
      g_NCMoveData.NCAXISDATA[8].AxisAbsPosition := Axis_S11.NCTOPLC.SETPOS;
    ELSE
      g_NCMoveData.NCAXISDATA[8].AxisAbsPosition := 0.0;
    END_IF;
    g_NCMoveData.NCAXISCMD[8].NCAxisAbs := TRUE;
  END_IF;
  IF g_nSusutainCount >= 12 THEN
    IF Axis_S12.NCTOPLC.SETPOS <= 0.0 THEN
      g_NCMoveData.NCAXISDATA[9].AxisAbsPosition := Axis_S12.NCTOPLC.SETPOS;
    ELSE
      g_NCMoveData.NCAXISDATA[9].AxisAbsPosition := 0.0;
    END_IF;
    g_NCMoveData.NCAXISCMD[9].NCAxisAbs := TRUE;
  END_IF;
  nFollowStep := 130;
  130: (*等下降轴到位*)
  bCheckAllDownFinish := TRUE;
  IF (g_nSusutainCount >= 1 AND g_bSustainAxis1UpFeedSafe) AND NOT(g_bSustain1AbsDone) THEN
    bCheckAllDownFinish := FALSE;
  END_IF;
  IF (g_nSusutainCount >= 2 AND g_bSustainAxis2UpFeedSafe) AND NOT(g_bSustain2AbsDone) THEN
    bCheckAllDownFinish := FALSE;
  END_IF;
  IF (g_nSusutainCount >= 3 AND g_bSustainAxis3UpFeedSafe) AND NOT(g_bSustain3AbsDone) THEN
    bCheckAllDownFinish := FALSE;
  END_IF;
  IF (g_nSusutainCount >= 4 AND g_bSustainAxis7UpFeedSafe) AND NOT(g_bSustain7AbsDone) THEN
    bCheckAllDownFinish := FALSE;
  END_IF;
  IF (g_nSusutainCount >= 5 AND g_bSustainAxis8UpFeedSafe) AND NOT(g_bSustain8AbsDone) THEN
    bCheckAllDownFinish := FALSE;
  END_IF;
  IF (g_nSusutainCount >= 6 AND g_bSustainAxis9UpFeedSafe) AND NOT(g_bSustain9AbsDone) THEN
    bCheckAllDownFinish := FALSE;
  END_IF;
  IF (g_nSusutainCount >= 7 AND g_bSustainAxisS7UpFeedSafe) AND NOT(g_NCMoveData.NCAXISDATA[4].AxisAbsMoveDone) THEN
    bCheckAllDownFinish := FALSE;
  END_IF;
  IF (g_nSusutainCount >= 8 AND g_bSustainAxisS8UpFeedSafe) AND NOT(g_NCMoveData.NCAXISDATA[5].AxisAbsMoveDone) THEN
    bCheckAllDownFinish := FALSE;
  END_IF;
  IF (g_nSusutainCount >= 9 AND g_bSustainAxisS9UpFeedSafe) AND NOT(g_NCMoveData.NCAXISDATA[6].AxisAbsMoveDone) THEN
    bCheckAllDownFinish := FALSE;
  END_IF;
  IF (g_nSusutainCount >= 10 AND g_bSustainAxisS10UpFeedSafe) AND NOT(g_NCMoveData.NCAXISDATA[7].AxisAbsMoveDone) THEN
    bCheckAllDownFinish := FALSE;
  END_IF;
  IF (g_nSusutainCount >= 11 AND g_bSustainAxisS11UpFeedSafe) AND NOT(g_NCMoveData.NCAXISDATA[8].AxisAbsMoveDone) THEN
    bCheckAllDownFinish := FALSE;
  END_IF;
  IF (g_nSusutainCount >= 12 AND g_bSustainAxisS12UpFeedSafe) AND NOT(g_NCMoveData.NCAXISDATA[9].AxisAbsMoveDone) THEN
    bCheckAllDownFinish := FALSE;
  END_IF;
  IF bCheckAllDownFinish THEN
    g_boSustainUpDownDone := TRUE;
    g_bSustainUpDownDone := TRUE;
    M.ENABLE[193] := 0;
    g_bExecuteFinishedM193 := FALSE;
    g_bFinishedM193_1 := FALSE;
    nFollowStep := 0;
  END_IF;
END_CASE;

