(*支撑轴1*)
CASE nSustainAxis1FollowState OF
  0:
  nSustainAxis1FollowState := 0;
  10:
  IF bSustainAxis1FloatEnable THEN
	g_bSustain1AbsPosition := g_fSustain1ToChuckDist - g_fSustainTargetPos;
    g_bSustainAxis1VelAddEnable := TRUE;
    g_bSustain1Abs := TRUE;
    nSustainAxis1FollowState := 130;
  ELSE
    nSustainAxis1FollowState := 0;
    M.ENABLE[193] := 0;
    g_bExecuteFinishedM193 := FALSE;
    g_bFinishedM193_11 := FALSE;
  END_IF;
  100:
  g_bSustainAxis1VelAddEnable := FALSE;
  nSustainAxis1FollowState := 110;
  110:
  g_bSustain1Abs := TRUE;
  IF Axis_Sustain1.NCTOPLC.SETPOS <= 0.0 THEN
    g_bSustain1AbsPosition := Axis_Sustain1.NCTOPLC.SETPOS;
  ELSE
    g_bSustain1AbsPosition := 0.0;
  END_IF;
  nSustainAxis1FollowState := 130;
  130:
  IF g_bSustain1AbsDone THEN
    g_boSustainUpDownDone := TRUE;
    g_bSustainUpDownDone := TRUE;
    M.ENABLE[193] := 0;
    g_bExecuteFinishedM193 := FALSE;
    g_bFinishedM193_11 := FALSE;
    nSustainAxis1FollowState := 0;
  END_IF;
END_CASE;

